function ActivityCakeShopTaskDialog:RequestShow()
    local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
    GameUtils.Request(Interfaces.OverseaActivityCatParadiseTask,{activityUuid = activityData.id},function(request,response)
        if checkInt(response.errCode) == 0 then
            self.limitTaskData = response.data.tasks
            self.dailyTaskData = response.data.dailyTasks
            self.taskCountDown = response.data.taskCountdown
            self.dailyTaskCountDown = response.data.dailyTaskCountdown
            self:RefreshShow()
        end
    end)
end

function ActivityCakeShopTaskDialog:RefreshShow()
    GameUtils.ReloadData(self.TabSv, #self.tabData)
    self:PreSelect()
    self:RefreshTabTaskNum()
end

function ActivityCakeShopTaskDialog:PreSelect()
    local preSelect = 1
    local cellItem = self.TabSv:GetShownItemByItemIndex(preSelect - 1)
    if not isNull(cellItem) then
        local env = CfUtils.GetLuaScr(cellItem,TabCellPath)
        if not isNull(env) then
            env:OnBtnTabClick()
        end
    end
end

function ActivityCakeShopTaskDialog:OnUpdateTaskListCellHandler_(listView, index, row, column)
    local cell = listView:NewListViewItem("Cell")
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell, TaskCellPath)
        if not isNull(env) then
            local data = self.taskData[index]
            env:SetClickButtonAction(function(index)
                self:OnTaskCellClick(index)
            end, index)
            env:RefreshShow(data,self.taskType)
        end
    end
    return cell
end

function ActivityCakeShopTaskDialog:OnUpdateTabListCellHandler_(listView, index, row, column)
    local cell = listView:NewListViewItem("Cell")
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell, TabCellPath)
        if not isNull(env) then
            local data = self.tabData[index]
            env:SetClickButtonAction(function(index)
                self:OnTabClick(index)
            end, index)
            env:RefreshShow(data)
        end
    end
    return cell
end

function ActivityCakeShopTaskDialog:OnTabClick(index)
    if not isNull(self.index) and self.index == index then
        return
    end

    if not isNull(self.index) then
        local cellItem = self.TabSv:GetShownItemByItemIndex(self.index - 1)
        if not isNull(cellItem) then
            local env = CfUtils.GetLuaScr(cellItem,TabCellPath)
            if not isNull(env) then
                env:DoSelect()
            end
        end
    end

    self.index = index
    if not isNull(self.index) then
        local cellItem = self.TabSv:GetShownItemByItemIndex(index - 1)
        if not isNull(cellItem) then
            local env = CfUtils.GetLuaScr(cellItem,TabCellPath)
            if not isNull(env) then
                env:OnSelect()
            end
        end
    end
    self.taskType = self.tabData[self.index].taskType
    self:RefreshRightShow()

end

function ActivityCakeShopTaskDialog:RefreshRightShow()
    self.taskData = self:GetTaskDataByTabData()
    table.sort(self.taskData,function(a,b)
        local aIsGet = a.status == 2 and 1 or 0
        local bIsGet = b.status == 2 and 1 or 0
        if aIsGet == bIsGet then
            local aCanGet = a.status == 1 and 1 or 0
            local bCanGet = b.status == 1 and 1 or 0
            if aCanGet == bCanGet then
                return a.id < b.id
            else
               return aCanGet > bCanGet
            end
        else
            return aIsGet < bIsGet
        end
    end)

    GameUtils.ReloadData(self.RewardLoopView, #self.taskData)
end

function ActivityCakeShopTaskDialog:GetTaskDataByTabData()
    if self.taskType == ActivityCakeUtils.TaskType.DailyTask then
        return self.dailyTaskData
    elseif self.taskType == ActivityCakeUtils.TaskType.LimitTask then
        return self.limitTaskData
    end
    return {}
end

function ActivityCakeShopTaskDialog:OnTaskCellClick(index)
    local data = self.taskData[index]
    if not isNull(data) then
        local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
        GameUtils.Request(Interfaces.OverseaActivityCatParadiseReceiveTaskReward,{ activityUuid = activityData.id,taskType = self.taskType, taskId = data.id },function(request,response)
            if checkInt(response.errCode) == 0 then
                local responseData = response.data
                if table.count(responseData.rewards) then
                    GoodsUtils.DrawRewards(responseData.rewards)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                end
                data.status = 2
                self:RefreshRightShow()
                self:RefreshTabTaskNum()
            end
        end)
    end
end

function ActivityCakeShopTaskDialog:RefreshTabTaskNum()
    for i, v in ipairs(self.tabData) do
        local cellItem = self.TabSv:GetShownItemByItemIndex(i - 1)
        if not isNull(cellItem) then
            local env = CfUtils.GetLuaScr(cellItem,TabCellPath)
            if not isNull(env) then
                local type = self.tabData[i].taskType
                local showTxt,redPoint = self:GetTaskShowNumAndRedPoint(type)
                env:RefreshTaskNum(showTxt)
                env:RefreshRedPoint(redPoint)
            end
        end
    end
end

function ActivityCakeShopTaskDialog:HaveRedPoint(i)
    local data
    if i == ActivityCakeUtils.TaskType.DailyTask then
        data = self.dailyTaskData
    elseif i == ActivityCakeUtils.TaskType.LimitTask then
        data = self.limitTaskData
    end
    local HaveRedPoint = false
    for i, v in pairs(data) do
        if v.status == 1 then
            HaveRedPoint = true
            break
        end
    end
    return HaveRedPoint
end

function ActivityCakeShopTaskDialog:GetTaskShowNumAndRedPoint(i)
    local data
    if i == ActivityCakeUtils.TaskType.DailyTask then
        data = self.dailyTaskData
    elseif i == ActivityCakeUtils.TaskType.LimitTask then
        data = self.limitTaskData
    end
    local maxNum = table.count(data)
    local curNum = 0
    local haveRedPoint = false
    for i, v in pairs(data) do
        if v.status == 2 then
            curNum = curNum + 1
        end
        if v.status == 1 then
            haveRedPoint = true
        end
    end
    return table.concat({curNum,"/",maxNum}),haveRedPoint
end

function ActivityCakeShopTaskDialog:OnBtnOneKeyGet()
    local isCanDraw = self:IsCanDraw()
    if not isCanDraw then
        GameUtils.Toast(localize("暂无可领取的奖励"))
        return
    end

    local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
    GameUtils.Request(Interfaces.OverseaActivityCatParadiseReceiveTaskReward,{ activityUuid = activityData.id,taskType = self.taskType, taskId = 0 },function(request,response)
        if checkInt(response.errCode) == 0 then
            local responseData = response.data
            if table.count(responseData.rewards) then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
            end
            self:UpdateTaskData()
            self:RefreshRightShow()
            self:RefreshTabTaskNum()
        end
    end)
end

function ActivityCakeShopTaskDialog:UpdateTaskData()
    for i, v in pairs(self.taskData) do
        if v.status == 1 then
            v.status = 2
        end
    end
end

function ActivityCakeShopTaskDialog:IsCanDraw()
    for i, v in pairs(self.taskData) do
        if v.status == 1 then
            return true
        end
    end
    return false
end

return ActivityCakeShopTaskDialog